import{f as e,c as t,o as r,ah as i}from"./chunks/framework.5bt9HFMa.js";const g=JSON.parse('{"title":"第三章 UML 基础与建模实践","description":"UML基础知识、各类图表的使用方法及如何用UML表达设计模式。","frontmatter":{"title":"第三章 UML 基础与建模实践","date":"2025-11-19T00:00:00.000Z","description":"UML基础知识、各类图表的使用方法及如何用UML表达设计模式。"},"headers":[],"relativePath":"series/软件设计体系结构/03-UML基础与建模实践.md","filePath":"series/软件设计体系结构/03-UML基础与建模实践.md","lastUpdated":1763971678000}'),l={name:"series/软件设计体系结构/03-UML基础与建模实践.md"};function o(s,a,n,d,h,_){return r(),t("div",null,a[0]||(a[0]=[i('<h1 id="第三章-uml-基础与建模实践" tabindex="-1">第三章 UML 基础与建模实践 <a class="header-anchor" href="#第三章-uml-基础与建模实践" aria-label="Permalink to &quot;第三章 UML 基础与建模实践&quot;">​</a></h1><h2 id="_3-1-uml-简介与应用场景" tabindex="-1">3.1 UML 简介与应用场景 <a class="header-anchor" href="#_3-1-uml-简介与应用场景" aria-label="Permalink to &quot;3.1 UML 简介与应用场景&quot;">​</a></h2><p>UML（Unified Modeling Language）是一种标准的建模语言，用于描述软件系统的结构和行为。</p><p><strong>应用场景：</strong></p><ul><li>系统设计与分析</li><li>团队沟通</li><li>文档记录</li></ul><h2 id="_3-2-类图-class-diagram-结构建模核心" tabindex="-1">3.2 类图（Class Diagram）：结构建模核心 <a class="header-anchor" href="#_3-2-类图-class-diagram-结构建模核心" aria-label="Permalink to &quot;3.2 类图（Class Diagram）：结构建模核心&quot;">​</a></h2><p>类图用于表示系统中的类及其之间的关系：</p><ul><li><strong>继承关系</strong>（Inheritance）</li><li><strong>关联关系</strong>（Association）</li><li><strong>聚合关系</strong>（Aggregation）</li><li><strong>组合关系</strong>（Composition）</li><li><strong>依赖关系</strong>（Dependency）</li><li><strong>实现关系</strong>（Realization）</li></ul><h2 id="_3-3-时序图-sequence-diagram-行为交互分析" tabindex="-1">3.3 时序图（Sequence Diagram）：行为交互分析 <a class="header-anchor" href="#_3-3-时序图-sequence-diagram-行为交互分析" aria-label="Permalink to &quot;3.3 时序图（Sequence Diagram）：行为交互分析&quot;">​</a></h2><p>时序图用于展示对象之间的交互顺序和时间。</p><h2 id="_3-4-状态图-state-diagram-状态机建模" tabindex="-1">3.4 状态图（State Diagram）：状态机建模 <a class="header-anchor" href="#_3-4-状态图-state-diagram-状态机建模" aria-label="Permalink to &quot;3.4 状态图（State Diagram）：状态机建模&quot;">​</a></h2><p>状态图用于描述对象在不同状态间的转换。</p><h2 id="_3-5-组件图与部署图简介" tabindex="-1">3.5 组件图与部署图简介 <a class="header-anchor" href="#_3-5-组件图与部署图简介" aria-label="Permalink to &quot;3.5 组件图与部署图简介&quot;">​</a></h2><ul><li><strong>组件图</strong>：描述系统的物理结构</li><li><strong>部署图</strong>：展示系统的部署架构</li></ul><h2 id="_3-6-如何用-uml-表达设计模式" tabindex="-1">3.6 如何用 UML 表达设计模式？ <a class="header-anchor" href="#_3-6-如何用-uml-表达设计模式" aria-label="Permalink to &quot;3.6 如何用 UML 表达设计模式？&quot;">​</a></h2><p>设计模式可以用UML类图清晰地表达。</p><hr><p>更多内容敬请期待...</p>',18)]))}const u=e(l,[["render",o]]);export{g as __pageData,u as default};
